55 |     /// @notice Allow a giant LP to claim a % of the revenue received by the MEV and Fees Pool
56 |     function claimRewards(
57 |         address _recipient,
58 |         address[] calldata _stakingFundsVaults,
59 |         bytes[][] calldata _blsPublicKeysForKnots
60 |     ) external {
61 |         uint256 numOfVaults = _stakingFundsVaults.length;
62 |         require(numOfVaults > 0, "Empty array");
63 |         require(numOfVaults == _blsPublicKeysForKnots.length, "Inconsistent array lengths");
64 |         for (uint256 i; i < numOfVaults; ++i) {
65 |             StakingFundsVault(payable(_stakingFundsVaults[i])).claimRewards(
66 |                 address(this),
67 |                 _blsPublicKeysForKnots[i]
68 |             );
69 |         }
70 | 
71 |         updateAccumulatedETHPerLP();
72 | 
73 |         _distributeETHRewardsToUserForToken(
74 |             msg.sender,
75 |             address(lpTokenETH),
76 |             lpTokenETH.balanceOf(msg.sender),
77 |             _recipient
78 |         );
79 |     }
